import itertools
import math

def calculate_ratio_diff(e, f, g, h):
    """Calculates |ef - gh| / (fh)"""
    if f == 0 or h == 0:
        return float('inf')
    return abs(e * f - g * h) / (f * h)

S = [1, 2, 3, 4, 5]
max_ratio = 0.0

# Iterate over all subsets of size 4
for subset in itertools.combinations(S, 4):
    subset_list = list(subset)

    # Iterate over all permutations to assign roles (e, f, g, h)
    # We only need to check partitions, as the formula is symmetric regarding the order within the pair
    # but the denominator (fh) and the structure of the difference means we must check assignments.

    # We use all permutations and calculate the ratio directly.
    for p in itertools.permutations(subset_list):
        e, f, g, h = p

        # Check distinctness (guaranteed by itertools.permutations on subset of distinct numbers)

        ratio = calculate_ratio_diff(e, f, g, h)
        if ratio > max_ratio:
            max_ratio = ratio

print(f"The maximum ratio R = |ef - gh| / (fh) found for S={S} is: {max_ratio}")
